COMMENT ON COLUMN ATT_CLASSES.ATT_CLASS_ID IS 'the unique attribute class ids';
COMMENT ON COLUMN ATT_CLASSES.ATT_CLASS IS 'the corresponding classes for attributes';
COMMENT ON COLUMN IMG_OBJ.IMG_ID IS 'the id representing images';
COMMENT ON COLUMN IMG_OBJ.OBJ_SAMPLE_ID IS 'the id of the object sample';
COMMENT ON COLUMN IMG_OBJ.OBJ_CLASS_ID IS 'the id indicating class of the objects';
COMMENT ON COLUMN IMG_OBJ.X IS 'x coordinate';
COMMENT ON COLUMN IMG_OBJ.Y IS 'y coordinate';
COMMENT ON COLUMN IMG_OBJ.W IS 'width of the bounding box of the object';
COMMENT ON COLUMN IMG_OBJ.H IS 'height of the bounding box of the object';
ALTER TABLE IMG_OBJ MODIFY (H ANNOTATIONS (ADD value_description 'commonsense evidence:bounding box of the object: (x, y, W, H)'));
COMMENT ON COLUMN IMG_OBJ_ATT.IMG_ID IS 'id number of each image';
COMMENT ON COLUMN IMG_OBJ_ATT.ATT_CLASS_ID IS 'attribute class number for image';
ALTER TABLE IMG_OBJ_ATT MODIFY (ATT_CLASS_ID ANNOTATIONS (ADD value_description 'commonsense evidence:if one IMG_ID has many ATT_CLASS_ID, it refers to that this image has multiple attributes'));
COMMENT ON COLUMN IMG_OBJ_ATT.OBJ_SAMPLE_ID IS 'object sample id';
ALTER TABLE IMG_OBJ_ATT MODIFY (OBJ_SAMPLE_ID ANNOTATIONS (ADD value_description 'commonsense evidence:â¢ if one IMG_ID has many OBJ_SAMPLE_ID, it refers to that this image has multiple objectsâ¢ if one ATT_CLASS_ID has many OBJ_SAMPLE_ID, it refers to that this attribute is composed of multiple objects.'));
COMMENT ON COLUMN IMG_REL.IMG_ID IS 'the image id';
COMMENT ON COLUMN IMG_REL.PRED_CLASS_ID IS 'the prediction relationship class between objects';
ALTER TABLE IMG_REL MODIFY (PRED_CLASS_ID ANNOTATIONS (ADD value_description 'commonsense evidence:if OBJ1_SAMPLE_ID = OBJ2_SAMPLE_ID, this relationship is the self-relation.'));
COMMENT ON COLUMN IMG_REL.OBJ1_SAMPLE_ID IS 'the sample id of the first object';
COMMENT ON COLUMN IMG_REL.OBJ2_SAMPLE_ID IS 'the sample id of the second object';
ALTER TABLE IMG_REL MODIFY (OBJ2_SAMPLE_ID ANNOTATIONS (ADD value_description 'commonsense evidence:if (OBJ1_SAMPLE_ID, OBJ2_SAMPLE_ID) has multiple PRED_CLASS_ID, it means these two objects have multiple relations.'));
COMMENT ON COLUMN OBJ_CLASSES.OBJ_CLASS_ID IS 'unique id number identifying object classes';
COMMENT ON COLUMN OBJ_CLASSES.OBJ_CLASS IS 'the explanation about object classes';
COMMENT ON COLUMN PRED_CLASSES.PRED_CLASS_ID IS 'the unique prediction id for the class';
COMMENT ON COLUMN PRED_CLASSES.PRED_CLASS IS 'the caption for the prediction class id';